def _features(z):
    from itertools import combinations
    s = [np.ones(len(z)), z]
    for j in range(4):
        u = z[:, j:j + 1]
        s.extend([u ** 2, u ** 3, u ** 4, np.tanh(u), np.arctan(u), u / (1 + abs(u)), np.exp(-u * u / 2)])
    groups = []
    for (i, j) in combinations(range(4), 2):
        (u, v) = (z[:, i:i + 1], z[:, j:j + 1])
        g = [u * v, u * u * v, u * v * v, u * u * v * v, u ** 3 * v, u * v ** 3, u * v / (1 + 0.5 * (u * u + v * v))]
        for sign in (-1, 1):
            w = (u + sign * v) / 1.4
            g.extend([np.sin(w), np.cos(w), np.tanh(w), w / (1 + abs(w)), np.exp(-w * w / 2)])
        groups.append(np.column_stack(g))
    return (s, groups)
